package lista5While.bloco1;

public class Ex3 {
    public static void main(String[] args) {
                                                                                                                                                                                                                                                                                                                                                                                                                                        int contador;
                                                                                                                                                                                                                                                                                                                                                                                                                                        contador = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                        while (contador<100){
                                                                                                                                                                                                                                                                                                                                                                                                                                            if (contador%2==0){
                                                                                                                                                                                                                                                                                                                                                                                                                                                System.out.println(contador);
                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                            else{}
                                                                                                                                                                                                                                                                                                                                                                                                                                            contador++;
                                                                                                                                                                                                                                                                                                                                                                                                                                        }
    }
}
